<?php
require_once __DIR__.'/config/config.php';require_login();$uid=(int)$_SESSION['user_id'];$stmt=$conn->prepare('SELECT m.*,a.animal_code,a.name FROM movement_records m JOIN animals a ON a.id=m.animal_id WHERE a.owner_id=? ORDER BY m.movement_date DESC,m.id DESC');$stmt->bind_param('i',$uid);$stmt->execute();$rows=$stmt->get_result();$page_title='Movements';require __DIR__.'/includes/header.php';?>
<div class="page-actions"><div><p>Maintain an internal record of where an animal has moved.</p></div><a class="btn btn-primary" href="movement_add.php">＋ Record movement</a></div><div class="alert info">This is an internal record-keeping tool. It does not issue or replace official movement permits or regulatory documents.</div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Animal</th><th>Origin</th><th>Destination</th><th>Reason</th><th>Document ref.</th></tr></thead><tbody><?php if($rows->num_rows):while($r=$rows->fetch_assoc()):?><tr><td><?=e(date('d M Y',strtotime($r['movement_date'])))?></td><td class="animal-id"><?=e($r['animal_code'])?></td><td><?=e($r['origin_location'])?></td><td><?=e($r['destination_location'])?></td><td><?=e($r['movement_reason']?:'—')?></td><td><?=e($r['document_reference']?:'—')?></td></tr><?php endwhile;else:?><tr><td colspan="6" class="empty">No movements recorded yet.</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/includes/footer.php';?>
